-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
-- Only the P99 grammar-manual hand-in is enabled; Halloween task 500220 and its later rewards are excluded.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Ahoy, " .. e.other:GetCleanName() .. ". Welcome ta the brig. I didn't get ta the B section of my piratisms manual. So, ya here ta stay or just visitin'?")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 18962 }) then
    e.self:Say("Wow. Ya actually got one. Thanks, mate! Here, you can have my cuffs. I'm tired of 'em and they're startin' ta chafe.")
    e.other:SummonItem(30041)
    e.other:AddEXP(10000)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
